def longest_palindromic_substring(s: str) -> str:
    if not s:
        return ""

    n = len(s)
    if n == 1:
        return s

    start, end = 0, 0

    for i in range(n):
        # Odd length palindrome
        left, right = i, i
        while left >= 0 and right < n and s[left] == s[right]:
            if right - left + 1 > end - start:
                start, end = left, right
        left -= 1
        right += 1

        # Even length palindrome
        left, right = i, i + 1
        while left >= 0 and right < n and s[left] == s[right]:
            if right - left + 1 > end - start:
                start, end = left, right
            left -= 1
            right += 1

    return s[start:end+1]
