def next_greater_element(n):
    s = str(n)
    n_len = len(s)
    if n_len == 1:
        return -1
    # Find the first index from the right where a digit is smaller than the next digit
    for i in range(n_len - 2, -1, -1):
        if s[i] < s[i + 1]:
            break
    else:
        # No such index found, no greater permutation exists
        return -1
    # Find the smallest digit to the right of i that is greater than s[i]
    for j in range(n_len - 1, i, -1):
        if s[j] > s[i]:
            break
    # Swap the found digits
    s[i], s[j] = s[j], s[i]
    # Reverse the suffix to get the smallest possible number
    s[i + 1:] = s[i + 1:][::-1]
    return int(s)
