    if stones <= 1:
        return False

    # If the current player can remove 3 stones and win, return True
    if stones == 3:
        return True

    # Check if the current player can force a win by removing 1, 2, or 3 stones
    # If any of these moves leaves the opponent in a losing position, the current player wins
    if stones % 3 == 0:
