def find_min_in_matrix(matrix):
    n = len(matrix)
    m = len(matrix[0])

    def merge(left, right):
        i = j = 0
        min_val = float('inf')
        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                min_val = left[i]
                i += 1
            else:
                min_val = right[j]
                j += 1
        while i < len(left):
            min_val = min(min_val, left[i])
            i += 1
        while j < len(right):
            min_val = min(min_val, right[j])
            j += 1
        return min_val

    def divide_and_conquer(matrix, start_row, end_row, start_col, end_col):
