        mid_col = (start_col + end_col) // 2
        left = divide_and_conquer(matrix, start_row, mid_row, start_col, mid_col)
        right = divide_and_conquer(matrix, mid_row + 1, end_row, mid_col + 1, end_col)
        return merge(left, right)

    return divide_and_conquer(matrix, 0, n - 1, 0, m - 1)
