def find_first_non_empty_text(root):
    """
    Perform a depth-first search to find the first non-empty text in a tree-like structure.
    Returns the first non-empty text found, or an empty string if none exists.
    Handles circular references without infinite loops.
    """
    if not root:
        return ""

    def dfs(node):
        if not node:
            return ""

        # Check if current node has non-empty text
        if node.text:
            return node.text

        # Recursively search children
        for child in node.children:
            result = dfs(child)
            if result:
                return result

        return ""

    return dfs(root)
