def find_prime_factors(num):
    if num <= 1:
        return []
    factors = []
    # Handle factor 2
    while num % 2 == 0:
        factors.append(2)
        num //= 2
    # Check odd factors up to sqrt(num)
    i = 3
    while i * i <= num:
        while num % i == 0:
            factors.append(i)
            num //= i
        i += 2
    # If remaining num is a prime > 2
    if num > 2:
        factors.append(num)
    return factors

